static void loadPresets(){for(int i=0;i<5;++i){auto s=L"Advanced"+std::to_wstring(i+1);presets[i].app=iniGet(s,L"App");presets[i].protocol=std::max(0,std::min(2,iniInt(s,L"Protocol",0)));presets[i].direction=std::max(0,std::min(2,iniInt(s,L"Direction",0)));presets[i].localPort=(uint16_t)std::max(0,std::min(65535,iniInt(s,L"LocalPort",0)));presets[i].remote=iniGet(s,L"Remote");presets[i].remotePort=(uint16_t)std::max(0,std::min(65535,iniInt(s,L"RemotePort",0)));}currentPreset=std::max(0,std::min(4,iniInt(L"Advanced",L"Preset",0)));}
