static void scanTcp4(const std::wstring&app,std::vector<Flow>&out){ULONG n=0;GetExtendedTcpTable(nullptr,&n,FALSE,AF_INET,TCP_TABLE_OWNER_PID_ALL,0);std::vector<BYTE>m(n);auto*t=(PMIB_TCPTABLE_OWNER_PID)m.data();if(GetExtendedTcpTable(t,&n,FALSE,AF_INET,TCP_TABLE_OWNER_PID_ALL,0)!=NO_ERROR)return;for(DWORD i=0;i<t->dwNumEntries;++i){auto&r=t->table[i];if(!samePath(processPath(r.dwOwningPid),app)||r.dwRemoteAddr==0||r.dwRemotePort==0)continue;out.push_back({app,1,ipv4(r.dwLocalAddr),portFromDword(r.dwLocalPort),ipv4(r.dwRemoteAddr),portFromDword(r.dwRemotePort)});}}
static void scanTcp6(const std::wstring&app,std::vector<Flow>&out){ULONG n=0;GetExtendedTcpTable(nullptr,&n,FALSE,AF_INET6,TCP_TABLE_OWNER_PID_ALL,0);std::vector<BYTE>m(n);auto*t=(PMIB_TCP6TABLE_OWNER_PID)m.data();if(GetExtendedTcpTable(t,&n,FALSE,AF_INET6,TCP_TABLE_OWNER_PID_ALL,0)!=NO_ERROR)return;for(DWORD i=0;i<t->dwNumEntries;++i){auto&r=t->table[i];if(!samePath(processPath(r.dwOwningPid),app)||r.dwRemotePort==0)continue;out.push_back({app,1,ipv6(r.ucLocalAddr),portFromDword(r.dwLocalPort),ipv6(r.ucRemoteAddr),portFromDword(r.dwRemotePort)});}}
static void scanUdp4(const std::wstring&app,std::vector<Flow>&out){ULONG n=0;GetExtendedUdpTable(nullptr,&n,FALSE,AF_INET,UDP_TABLE_OWNER_PID,0);std::vector<BYTE>m(n);auto*t=(PMIB_UDPTABLE_OWNER_PID)m.data();if(GetExtendedUdpTable(t,&n,FALSE,AF_INET,UDP_TABLE_OWNER_PID,0)!=NO_ERROR)return;for(DWORD i=0;i<t->dwNumEntries;++i){auto&r=t->table[i];if(!samePath(processPath(r.dwOwningPid),app))continue;out.push_back({app,2,ipv4(r.dwLocalAddr),portFromDword(r.dwLocalPort),L"",0});}}
static void scanUdp6(const std::wstring&app,std::vector<Flow>&out){ULONG n=0;GetExtendedUdpTable(nullptr,&n,FALSE,AF_INET6,UDP_TABLE_OWNER_PID,0);std::vector<BYTE>m(n);auto*t=(PMIB_UDP6TABLE_OWNER_PID)m.data();if(GetExtendedUdpTable(t,&n,FALSE,AF_INET6,UDP_TABLE_OWNER_PID,0)!=NO_ERROR)return;for(DWORD i=0;i<t->dwNumEntries;++i){auto&r=t->table[i];if(!samePath(processPath(r.dwOwningPid),app))continue;out.push_back({app,2,ipv6(r.ucLocalAddr),portFromDword(r.dwLocalPort),L"",0});}}
static std::vector<Flow>scanFlows(const std::wstring&app){std::vector<Flow>o;if(app.empty())return o;scanTcp4(app,o);scanTcp6(app,o);scanUdp4(app,o);scanUdp6(app,o);return o;}
